try {
    $options = ConvertFrom-TaskForgeArguments -Arguments $CliArguments
    $defaultDataFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/tasks.json'
    $defaultConfigFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/config.json'
    $commandName = $Command.ToLowerInvariant()

    if ($commandName -eq 'config') {
        if ($CliArguments.Count -lt 1 -or $CliArguments[0].StartsWith('--')) {
            throw 'config requires an action: set, get, or list.'
        }
        $action = $CliArguments[0].ToLowerInvariant()
        $rest = @()
        if ($CliArguments.Count -gt 1) {
            $rest = $CliArguments[1..($CliArguments.Count - 1)]
        }
        $configOptions = ConvertFrom-TaskForgeArguments -Arguments $rest
        $configFile = if ($configOptions.Contains('config-file')) {
            Get-RequiredOption -Options $configOptions -Name 'config-file'
        }
        else {
            $defaultConfigFile
        }
        $configJson = $configOptions.Contains('json')
        $knownKeys = Get-TaskForgeConfigKeys

        switch ($action) {
            'set' {
                Assert-KnownOptions -Options $configOptions -Allowed @('key', 'value', 'config-file', 'json')
                $key = Get-RequiredOption -Options $configOptions -Name 'key'
                if ($key -notin $knownKeys) {
                    throw "Unknown config key: $key"
                }
                $value = Get-RequiredOption -Options $configOptions -Name 'value'
                $stored = if ($key -eq 'defaultJson') { ConvertTo-TaskForgeBoolean -Value $value } else { $value }
                $config = Read-TaskForgeConfig -Path $configFile
                $config[$key] = $stored
                Write-TaskForgeConfig -Path $configFile -Config $config
                if ($configJson) {
                    Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $key; value = $stored }) -AsJson $true
                }
                else {
                    "Set $key = $stored"
                }
            }
            'get' {
                Assert-KnownOptions -Options $configOptions -Allowed @('key', 'config-file', 'json')
                $key = Get-RequiredOption -Options $configOptions -Name 'key'
                if ($key -notin $knownKeys) {
                    throw "Unknown config key: $key"
                }
                $config = Read-TaskForgeConfig -Path $configFile
                $value = if ($config.Contains($key)) { $config[$key] } else { $null }
                if ($configJson) {
                    ConvertTo-Json -InputObject $value -Depth 8 -Compress
                }
                elseif ($null -eq $value) {
                    ''
                }
                else {
                    [string]$value
                }
            }
            'list' {
                Assert-KnownOptions -Options $configOptions -Allowed @('config-file', 'json')
                $config = Read-TaskForgeConfig -Path $configFile
                if ($configJson) {
                    $obj = [ordered]@{}
                    foreach ($k in $knownKeys) {
                        if ($config.Contains($k)) { $obj[$k] = $config[$k] }
                    }
                    ConvertTo-Json -InputObject ([pscustomobject]$obj) -Depth 8 -Compress
                }
                else {
                    $lines = @()
                    $bannerPath = Join-Path (Split-Path -Parent $PSScriptRoot) 'assets/config.txt'
                    if (Test-Path -LiteralPath $bannerPath) {
                        $lines += (Get-Content -LiteralPath $bannerPath -Raw).TrimEnd("`n")
                    }
                    $settings = @()
                    foreach ($k in $knownKeys) {
                        if ($config.Contains($k)) { $settings += ("{0} = {1}" -f $k, $config[$k]) }
                    }
                    if ($settings.Count -eq 0) { $settings += 'No configuration set.' }
                    $lines += $settings
                    $lines -join "`n"
                }
            }
            default {
                throw "Unknown config action: $action"
            }
        }
    }
    else {
        $configFile = if ($options.Contains('config-file')) {
            Get-RequiredOption -Options $options -Name 'config-file'
        }
        else {
            $defaultConfigFile
        }
        $config = Read-TaskForgeConfig -Path $configFile
        $dataFile = if ($options.Contains('data-file')) {
            Get-RequiredOption -Options $options -Name 'data-file'
        }
        elseif ($config.Contains('dataFile')) {
            Resolve-TaskForgeConfigPath -ConfigFile $configFile -Path ([string]$config['dataFile'])
        }
        else {
            $defaultDataFile
        }
        $asJson = if ($options.Contains('json')) {
            $true
        }
        elseif ($config.Contains('defaultJson')) {
            [bool]$config['defaultJson']
        }
        else {
            $false
        }

        switch ($commandName) {
            'add' {
                Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'config-file', 'json')
                $title = Get-RequiredOption -Options $options -Name 'title'
                $tasks = @(Read-TaskStore -Path $dataFile)
                $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
                $task = [ordered]@{
                    id = $nextId
                    title = $title.Trim()
                    description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
                    status = 'pending'
                    createdAt = [DateTimeOffset]::UtcNow.ToString('o')
                }
                Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
                if ($asJson) {
                    Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
                }
                else {
                    "Added task ${nextId}: $($task.title)"
                }
            }
            'list' {
                Assert-KnownOptions -Options $options -Allowed @('data-file', 'config-file', 'json')
                $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
                if ($asJson) {
                    Write-TaskForgeOutput -Value $tasks -AsJson $true
                }
                elseif ($tasks.Count -eq 0) {
                    'No tasks.'
                }
                else {
                    $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
                }
            }
            'complete' {
                Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'config-file', 'json')
                $idText = Get-RequiredOption -Options $options -Name 'id'
                $id = 0
                if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                    throw '--id must be a positive integer.'
                }
                $tasks = @(Read-TaskStore -Path $dataFile)
                $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
                if ($null -eq $task) {
                    throw "Task $id was not found."
                }
                $task.status = 'completed'
                Write-TaskStore -Path $dataFile -Tasks $tasks
                if ($asJson) {
                    Write-TaskForgeOutput -Value $task -AsJson $true
                }
                else {
                    "Completed task $id."
                }
            }
            'remove' {
                Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'config-file', 'json')
                $idText = Get-RequiredOption -Options $options -Name 'id'
                $id = 0
                if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                    throw '--id must be a positive integer.'
                }
                $tasks = @(Read-TaskStore -Path $dataFile)
                $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
                if ($remaining.Count -eq $tasks.Count) {
                    throw "Task $id was not found."
                }
                Write-TaskStore -Path $dataFile -Tasks $remaining
                $summary = [pscustomobject]@{ removedId = $id }
                if ($asJson) {
                    Write-TaskForgeOutput -Value $summary -AsJson $true
                }
                else {
                    "Removed task $id."
                }
            }
            'help' {
                Assert-KnownOptions -Options $options -Allowed @('config-file')
                @'
TaskForge
  add --title TEXT [--description TEXT] [--data-file PATH] [--config-file PATH] [--json]
  list [--data-file PATH] [--config-file PATH] [--json]
  complete --id ID [--data-file PATH] [--config-file PATH] [--json]
  remove --id ID [--data-file PATH] [--config-file PATH] [--json]
  config set --key KEY --value VALUE [--config-file PATH] [--json]
  config get --key KEY [--config-file PATH] [--json]
  config list [--config-file PATH] [--json]

Config keys: dataFile, defaultJson. Explicit options override configured defaults.
'@
            }
            default {
                throw "Unknown command: $Command"
            }
        }
    }
}

